with open(r'c:\Users\Admin\OneDrive\Desktop\web2\data\movies.json', 'r', encoding='utf-8') as f:
    existing_movies = json.load(f)['movies']

existing_titles_norm = {m['title'].lower().strip().replace(':', '').replace('-', ' '): m for m in existing_movies}

# Let's parse items from user_raw_text
pattern = r'(?:\*\*\s*)?([A-Za-z0-9\s:;,’\'-]+?)(?:\s*\*\*)?\s*\(((?:Movie|Series)[^\)]*)\)\s*[–-]\s*([^A-Z\n\r]+(?:(?![A-Z][a-z0-9\s:;,’\'-]+\s*\((?:Movie|Series))[^\n\r])*)'

# Let's also split by sections or find all matches
import re

items = re.findall(r'([A-Za-z0-9\s:;,’\'\.\-]+?)\s*\(((?:Movie|Series)[^\)]*)\)\s*[–-]\s*([^A-Z\r\n\t]+(?:(?![A-Z][a-zA-Z0-9\s:;,’\'\.\-]+\s*\((?:Movie|Series))[^\r\n])*)', user_raw_text)

print(f"Total parsed items: {len(items)}")
for title, mtype, desc in items:
    # clean title
    clean_title = title.strip().replace('**', '').strip()
    # clean title prefix if section header merged into it
    for cat in ["Artificial Intelligence, Cyberpunk & Robotics", "Time Travel & Multiverses", "Dystopian & Post-Apocalyptic", "Alien Contact & Invasions", "Mind-Bending & Hard Sci-Fi"]:
        if clean_title.startswith(cat):
            clean_title = clean_title[len(cat):].strip()
    norm = clean_title.lower().strip().replace(':', '').replace('-', ' ')
    if norm == 'sil0':
        clean_title = 'Silo'
        norm = 'silo'
    
    # Check if in existing
    found = False
    for k in existing_titles_norm:
        if norm in k or k in norm or norm == k:
            found = True
            matched_title = existing_titles_norm[k]['title']
            matched_id = existing_titles_norm[k]['id']
            break
    print(f"[{'EXISTS ('+str(matched_id)+': '+matched_title+')' if found else 'MISSING'}] {clean_title} | Type: {mtype.strip()} | Desc: {desc.strip()[:50]}...")
